<script setup lang="ts">import{onMounted,ref}from'vue';import{ElMessage}from'element-plus';import{api}from'../api/admin';const rows=ref<any[]>([]),detail=ref<any>(),visible=ref(false);async function load(){try{rows.value=await api.imports()as any[]}catch(e:any){ElMessage.error(e.message)}}async function show(id:number){try{detail.value=await api.importDetail(id);visible.value=true}catch(e:any){ElMessage.error(e.message)}}onMounted(load);</script>
<template><div class="page"><div class="page-heading"><div><h1>对账记录</h1><p>查看文件摘要、导入结果和确认状态。</p></div></div><div class="table-card"><el-table :data="rows"><el-table-column prop="fileName" label="文件名" min-width="220"/><el-table-column prop="fileHash" label="SHA-256" min-width="220"><template #default="s"><span class="code-text">{{s.row.fileHash}}</span></template></el-table-column><el-table-column prop="status" label="状态" width="110"/><el-table-column prop="totalCount" label="总数" width="80"/><el-table-column prop="successCount" label="成功" width="80"/><el-table-column prop="failedCount" label="失败" width="80"/><el-table-column prop="unmatchedCount" label="未匹配" width="90"/><el-table-column prop="operatorName" label="操作人" width="100"/><el-table-column prop="createdAt" label="导入时间" min-width="170"/><el-table-column label="操作" fixed="right" width="90"><template #default="s"><el-button link type="primary" @click="show(s.row.id)">明细</el-button></template></el-table-column></el-table></div><el-drawer v-model="visible" title="对账批次明细" size="75%"><el-table v-if="detail" :data="detail.rows"><el-table-column prop="rowNumber" label="行" width="60"/><el-table-column prop="umallOrderNo" label="UMALL订单号"/><el-table-column prop="iccid" label="ICCID"/><el-table-column prop="phone" label="手机号"/><el-table-column prop="matchedOrderId" label="匹配订单ID"/><el-table-column prop="matchMethod" label="匹配方式"/><el-table-column prop="matchStatus" label="结果"/><el-table-column prop="exceptionReason" label="异常原因"/></el-table></el-drawer></div></template>

